CREATE POLICY admin updates profiles ON profiles FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM profiles profiles_1
  WHERE ((profiles_1.id = ( SELECT auth.uid() AS uid)) AND (profiles_1.role = 'admin'::text)))));

CREATE POLICY boq_rows_delete_own ON boq_rows FOR DELETE TO public USING ((EXISTS ( SELECT 1
   FROM boqs
  WHERE ((boqs.id = boq_rows.boq_id) AND (boqs.user_id = auth.uid())))));

CREATE POLICY boq_rows_select_own ON boq_rows FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM boqs
  WHERE ((boqs.id = boq_rows.boq_id) AND (boqs.user_id = auth.uid())))));

CREATE POLICY boq_rows_update_own ON boq_rows FOR UPDATE TO public USING ((EXISTS ( SELECT 1
   FROM boqs
  WHERE ((boqs.id = boq_rows.boq_id) AND (boqs.user_id = auth.uid())))));

CREATE POLICY delete sequences ON device_sequences FOR DELETE TO public USING ((EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.role = 'admin'::text)))));

CREATE POLICY users read own device ON devices FOR SELECT TO public USING (((user_id = ( SELECT auth.uid() AS uid)) AND (EXISTS ( SELECT 1
   FROM profiles
  WHERE ((profiles.id = ( SELECT auth.uid() AS uid)) AND (profiles.is_approved = true))))));
